import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"4. Executed Test Baseline","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.8/part-02.md","filePath":"en/publications/implementation-case-i0.8/part-02.md","lastUpdated":1786339128000}'),n={name:"en/publications/implementation-case-i0.8/part-02.md"};function d(o,t,s,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>All primary product and full-suite runs were author-executed against fixed inputs. Skipped tests remain skips.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>S0.6 product C01–C14</td><td style="text-align:right;">14 PASS / 0 FAIL / 0 PARTIAL / 0 NOT RUN</td><td style="text-align:right;">0</td><td>Direct CodeFlowMu product Reader execution</td></tr><tr><td>CodeFlowMu internal TMPA</td><td style="text-align:right;">23/23</td><td style="text-align:right;">0</td><td>Includes explicit S0.5 compatibility and S0.6 regressions</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">5 valid + 3 expected-invalid fixtures</td><td style="text-align:right;">0</td><td>Product protocol tests, separate from TMPA verdict</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,485 passed, 0 failed, 1 skipped</td><td style="text-align:right;">0</td><td>Full author-local Runtime run</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">777 passed, 0 failed</td><td style="text-align:right;">0</td><td>Full author-local Shell run</td></tr><tr><td>FCoP locked reference baseline</td><td style="text-align:right;">1,210 passed, 2 skipped</td><td style="text-align:right;">0</td><td>Reference implementation, not protocol proof</td></tr><tr><td>Public reproducer</td><td style="text-align:right;"><code>npm ci</code> + 14/14 product PASS</td><td style="text-align:right;">0</td><td>Self-contained conformance-slice rerun</td></tr></tbody></table><p>The final conformance result validates against the S0.6 result schema. It records <code>product_reader_called: true</code>, <code>reference_reader_called: false</code>, implementation <code>codeflowmu/V1.6.0</code>, and evidence level <code>demonstrated</code>.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.6 criterion</th><th style="text-align:right;">Verdict</th><th>Executed observation</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;"><strong>PASS</strong></td><td>All four published S0.6 schemas compile; malformed structural and asserted <code>date-time</code> cases are rejected deterministically.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;"><strong>PASS</strong></td><td>Content-addressed revisions remain attributable, primary-carrier conflicts do not gain authority, and corrections remain separate evidence.</td></tr><tr><td>C03</td><td>Duplicate identity and provenance</td><td style="text-align:right;"><strong>PASS</strong></td><td>Different-content duplicates are quarantined; byte-identical observations project one node while retaining every deterministically ordered <code>source_id</code>.</td></tr><tr><td>C04</td><td>Serial continuity and asynchronous progress</td><td style="text-align:right;"><strong>PASS</strong></td><td>Stream gaps and duplicate sequences stay explicit, unrelated streams progress, and arrival order does not change output.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;"><strong>PASS</strong></td><td>Denied and undetermined authority branches remain distinct and cannot mutate reconstructed state.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;"><strong>PASS</strong></td><td>Illegal transitions are rejected; missing independent acceptance leaves completion undetermined and prevents advancement.</td></tr><tr><td>C07</td><td>Separation of duties and human approval</td><td style="text-align:right;"><strong>PASS</strong></td><td>Wrong approval type, missing assignment, disallowed role, missing approval decision, and self-approval remain <code>pending_human</code>; a valid assigned independent approval clears the gate.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;"><strong>PASS</strong></td><td>Covered-content tampering emits <code>INTEGRITY_MISMATCH</code>, excludes the object from authoritative nodes, and retains the failed source.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;"><strong>PASS</strong></td><td>Missing dependencies and claim evidence remain visible and propagate an undetermined result without inventing facts.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the affected prohibited-cycle subgraph is quarantined; unrelated valid nodes remain usable.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;"><strong>PASS</strong></td><td>Fixed-source permutations are byte-equivalent; canonical order is Unicode code-point order, including U+E000 before U+10000.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Contradictory reviews remain disputed until an authorized resolver acts; unauthorized decisions remain evidence but cannot clear the conflict.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;"><strong>PASS</strong></td><td>A fresh Reader reconstructs lifecycle, responsibility, dependencies, failures, recovery actions, and parent-child state consistently.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the accepted authorized chain reaches archive, while the prior task/report/review/transition history remains reconstructable.</td></tr></tbody></table><h1 id="_6-s0-5-to-s0-6-product-delta" tabindex="-1">6. S0.5 to S0.6 Product Delta <a class="header-anchor" href="#_6-s0-5-to-s0-6-product-delta" aria-label="Permalink to &quot;6. S0.5 to S0.6 Product Delta&quot;">​</a></h1><h2 id="_6-1-c03-—-aggregation-without-provenance-loss" tabindex="-1">6.1 C03 — aggregation without provenance loss <a class="header-anchor" href="#_6-1-c03-—-aggregation-without-provenance-loss" aria-label="Permalink to &quot;6.1 C03 — aggregation without provenance loss&quot;">​</a></h2><p>I0.7 demonstrated conflict handling for same-ID, different-content candidates. S0.6 adds a second boundary: multiple byte-identical observations must not create duplicate nodes, but aggregation must not erase where those observations came from. V1.6.0 emits one canonical node with the complete, code-point-sorted <code>source_ids</code> list.</p><h2 id="_6-2-c07-—-approval-is-an-authorized-governance-object" tabindex="-1">6.2 C07 — approval is an authorized governance object <a class="header-anchor" href="#_6-2-c07-—-approval-is-an-authorized-governance-object" aria-label="Permalink to &quot;6.2 C07 — approval is an authorized governance object&quot;">​</a></h2><p>The S0.5 baseline demonstrated role separation and a high-risk human gate. S0.6 makes the authorization contract directly testable. An approval counts only when its object type is permitted, the actor has a matching Assignment, the role is allowed, the body carries an approval decision, and the actor is independent when the Profile requires it. Four negative branches remain pending rather than being treated as implicit approval.</p><h2 id="_6-3-c11-—-deterministic-means-locale-independent" tabindex="-1">6.3 C11 — deterministic means locale-independent <a class="header-anchor" href="#_6-3-c11-—-deterministic-means-locale-independent" aria-label="Permalink to &quot;6.3 C11 — deterministic means locale-independent&quot;">​</a></h2><p>S0.6 removes environmental ambiguity from canonical sorting. V1.6.0 replaces locale-dependent comparison with Unicode code-point ordering throughout object keys, sources, graph traversal, issues, and output collections. The U+E000/U+10000 fixture detects the UTF-16 code-unit ordering mistake that can otherwise pass ordinary ASCII tests.</p><h2 id="_6-4-compatibility-boundary" tabindex="-1">6.4 Compatibility boundary <a class="header-anchor" href="#_6-4-compatibility-boundary" aria-label="Permalink to &quot;6.4 Compatibility boundary&quot;">​</a></h2><p>CodeFlowMu&#39;s internal suite includes an explicit S0.5/I0.7 compatibility path. I0.7 remains the exact historical S0.5 product result; I0.8 does not rewrite its inputs, criteria, product version, or evidence package.</p><h1 id="_7-public-reproducer" tabindex="-1">7. Public Reproducer <a class="header-anchor" href="#_7-public-reproducer" aria-label="Permalink to &quot;7. Public Reproducer&quot;">​</a></h1><p>The formal archive contains a 29-file self-contained reproducer with a package lock, the product Reader, Protocol Validator, Profile, Fixtures, Runner, and exact official inputs. It requires Node.js 22 or newer and public npm registry access:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd public-reproducer</span></span>
<span class="line"><span>npm ci</span></span>
<span class="line"><span>npm test</span></span></code></pre></div><p>The test first verifies all seven upstream SHA-256 values, then calls the bundled CodeFlowMu <code>GovernanceReader</code>. The recorded clean-copy run and publication preflight both produce 14 PASS / 0 FAIL. The reproducer makes the conformance slice publicly inspectable without asserting that the private mother repository or full application is public.</p><h1 id="_8-retained-wp-13-evidence-gating-case" tabindex="-1">8. Retained WP-13 Evidence-Gating Case <a class="header-anchor" href="#_8-retained-wp-13-evidence-gating-case" aria-label="Permalink to &quot;8. Retained WP-13 Evidence-Gating Case&quot;">​</a></h1><p>WP-13 remains relevant to the engineering interpretation but is not rerun in I0.8. It records a role-separated workflow in which a completion-meaning claim was held until persistent evidence, a formal report, and QA verification existed. A later Gate C decision accepted delivery while activation, push/publication, and archive remained separate decisions.</p><p>This case supports evidence gating, staged authority, and same-task recovery. It does not prove hallucination elimination, universal false-claim detection, or S0.6 conformance. The C01–C14 result comes from the V1.6.0 product bundle, not from WP-13.</p>`,22)])])}const g=e(n,[["render",d]]);export{u as __pageData,g as default};
